INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandals-wl7554-purple', 'Women''s Daily Wear Sandals  - WL7554 Purple', 'WALKAROO', 'Sandals', 'Step into everyday elegance and comfort with the Walkaroo Women''s WL7554 Purple Daily Wear Sandal. Designed for women who prefer stylish yet comfortable footwear, this sandal combines a premium double-strap design, soft Cushion Sole comfort, and a lightweight PU sole for effortless daily wear.
The sandal features a fashionable double strap design with metallic buckle detailing that adds a stylish and premium touch. The broad upper straps provide better foot coverage and support, while the open-toe construction ensures breathability and ease during regular use. The smooth textured upper gives the sandal a refined look suitable for casual and everyday styling.
The PU sole provides lightweight cushioning, flexibility, and durability for daily movement. The Cushion Sole footbed offers a soft underfoot feel, helping provide comfort during extended wear. The textured outsole improves grip and stability on regular surfaces, making it suitable for shopping, travel, home wear, and casual outing', 359.0, 359.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/1_8a716e63-85ac-47c5-be60-45792f9ccc82.jpg?v=1786511145&width=1920', '["https://www.walkaroo.in/cdn/shop/files/1_8a716e63-85ac-47c5-be60-45792f9ccc82.jpg?v=1786511145&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
