INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-sports-sneakers-sge24005-white-beige', 'Men''s Sports Sneakers - SGE24005 White Beige', 'WALKAROO SPORTZ', 'Sneakers', 'Elevate your active lifestyle with the WALKAROO lace-up sports sneakers. These lightweight kicks feature a breathable outer material that keeps your feet cool and dry during intense workouts. The secure lace-up design ensures a customized fit, while the flexible sole provides excellent traction and support. Whether you''re hitting the gym or going for a run, these sneakers are the perfect choice for active individuals seeking style and functionality.', 779.0, 1199.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/1_9a331851-fc0a-46d8-a5d2-b1c6322b6823.jpg?v=1786512162&width=1920', '["https://www.walkaroo.in/cdn/shop/files/1_9a331851-fc0a-46d8-a5d2-b1c6322b6823.jpg?v=1786512162&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
