INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-sandals-wgp53302-brown', 'Men''s Daily Wear Sandals - WGP53302 Brown', 'WALKAROO PLUS', 'Sandals', 'Walkaroo WGP53302 is a men’s brown daily wear sandal designed for everyday comfort, casual style, and dependable use. Built with a synthetic leather upper in a suede-finish look, this men’s T-strap sandal combines a smart dual-tone appearance with practical comfort features for regular wear. The open toe-post construction, buckle adjustment, soft cushioned insole, and PU sole make it a reliable choice for men who want a value-for-money sandal for daily walking, errands, and casual outings.

Whether shoppers search for a men’s sandal, men’s chappal, men’s comfort sandal, men’s toe-post sandal, men’s buckle sandal, men’s casual slipper, men’s open sandal, or men’s brown comfort chappal, this style is designed to match that intent with comfort-led everyday performance.

Key Features

  Men’s daily wear sandal in brown dual-tone finish
  Synthetic leather upper with suede-look texture
  T-strap toe-post design for a secure and supportive feel
  Buckle adjustment for a more personalized fit', 499.0, 499.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/WGP53302-BROWN-GENTS_5f8de3ef-a474-4dd7-bfe1-b23f6c325d0f.jpg?v=1786511241&width=1920', '["https://www.walkaroo.in/cdn/shop/files/WGP53302-BROWN-GENTS_5f8de3ef-a474-4dd7-bfe1-b23f6c325d0f.jpg?v=1786511241&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
