INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-sports-shoes-xs9771-black-yellow', 'Walkaroo Men Walking and Washable Shoes - XS9771 Black Yellow', 'WALKAROO', 'Athletic Shoes', 'These lace up shoes from Walkaroo are sturdier & light in weight. They are comfortable & provide support to your feet. Pick different prints & pattern to get a fun & cool look. You can pair it up with your jeans, tracks, sweatpants, shorts or chinos for a casual & sporty look. You can use it for activities such as gym, tennis, running, athletic, workout, walking etc. or also as a fashion statement. Care instructions: Allow the footwear to de-odorize regularly. Dust the surface using a clean cloth to remove the dirt.', 889.0, 889.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/3_51025568-51a8-4db8-999f-cb32412e5620.jpg?v=1786513753&width=1920', '["https://www.walkaroo.in/cdn/shop/files/3_51025568-51a8-4db8-999f-cb32412e5620.jpg?v=1786513753&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-sandals-wgr53246-dark-green', 'Men''s Daily Wear Sandals - WGR53246 Dark Green', 'WALKAROO', 'Sandals', 'Step into modern style and exceptional comfort with the Walkaroo Men''s WGR53246  Dark Green Daily Wear Sandal . This sandal is engineered for the discerning man seeking a stylish yet incredibly comfortable option for everyday wear, promising superior cushioning through its "CUSHION SOLE" technology .
It features a striking Dual Tone  color combination: a rich Dark Green for the main upper strap and outsole, complemented by a lighter Tan/Dark Green footbed and mid-sole layer . The upper is made from durable Rexine, providing a smooth, consistent finish that''s easy to maintain. The design boasts a modern T-strap  with a secure toe-loop  and a broad midfoot strap adorned with a decorative, non-functional metallic buckle , adding a touch of sophisticated flair. The footbed prominently features "HUESTEP" branding .
