INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-slip-on-walking-shoe-ws3266-peach', 'Women''s Slip-on Walking Shoe - WS3266 Peach', 'WALKAROO', 'Athletic Shoes', 'Step into comfort and style with the WALKAROO Women''s Sports Walking Shoe. Designed to keep you moving throughout the day, these shoes feature a slip-on closure for easy wear and a secure fit without the hassle of laces. The breathable mesh upper ensures superior airflow, keeping your feet cool and fresh, even during extended walks. With a perfect fit that adapts to your foot shape, these shoes offer unparalleled comfort for all-day wear. Lightweight and stylish, they provide the ideal balance of performance and fashion. Whether you''re out for a walk or running errands, these shoes will keep you comfortable and on-trend every step of the way.', 649.0, 649.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/01_83287a2a-a233-4e2c-9793-85ebc352bef8.jpg?v=1786512681&width=1920', '["https://www.walkaroo.in/cdn/shop/files/01_83287a2a-a233-4e2c-9793-85ebc352bef8.jpg?v=1786512681&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
