INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-clogs-wc8778-aqua-blue', 'Men''s Clogs  -  WC8778 Aqua Blue', 'WALKAROO', 'Slippers', 'Step into unparalleled comfort and standout style with the Walkaroo Men''s WC8778 Aquablue Clogs. This pair distinguishes itself significantly from competitors through its unique colours and innovative **design**, in addition to its superior comfort and exceptional value.
