INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-mens-clogs-wc8732-black', 'Men''s Clogs  - WC8732 Black', 'WALKAROO', 'Slippers', 'These men''s clogs are the perfect combination of comfort and practicality. Crafted from durable EVA material, they are designed to withstand daily wear while offering exceptional lightness and flexibility. The breathable design ensures your feet stay cool and comfortable, even during extended periods of use. Ideal for both indoor and outdoor activities, these clogs provide a reliable, long-lasting option for anyone seeking everyday footwear that doesn''t compromise on comfort or style. Whether you''re running errands, lounging at home, or spending time outdoors, these clogs are a versatile addition to your footwear collection.', 345.0, 354.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/WC8732-BLACK-1_43e2f2c1-030e-4a71-beed-ccdb4352ff07.jpg?v=1786512759&width=1920', '["https://www.walkaroo.in/cdn/shop/files/WC8732-BLACK-1_43e2f2c1-030e-4a71-beed-ccdb4352ff07.jpg?v=1786512759&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
