INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-sports-shoe-ws9132-black', 'Men''s Lace-up Sports Shoes - WS9132 Black', 'WALKAROO SPORTZ', 'Athletic Shoes', 'These lace up shoes from Walkaroo are sturdier & light in weight. They are comfortable & provide support to your feet. Pick different prints & pattern to get a fun & cool look. You can pair it up with your jeans, tracks, sweatpants, shorts or chinos for a casual & sporty look. You can use it for activities such as gym, tennis, running, athletic, workout, walking etc. or also as a fashion statement. Care instructions: Allow the footwear to de-odorize regularly. Dust the surface using a clean cloth to remove the dirt.', 978.0, 999.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/01_655e60cc-9a23-495f-8bf6-a09ed9efa9ec.jpg?v=1786513093&width=1920', '["https://www.walkaroo.in/cdn/shop/files/01_655e60cc-9a23-495f-8bf6-a09ed9efa9ec.jpg?v=1786513093&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-casuals-sandals-wf6255-brown', 'Men''s Roman Sandals  - WF6255 Brown', 'WALKAROO', 'Sandals', 'Experience the perfect fusion of comfort, style, and versatility with the Walkaroo Xgo Men''s Solid Roman Sandals - WF6255 in Brown. Featuring a closed-toe design, these sandals offer the structured support of a shoe combined with the breathability of a sandal, making them an ideal hybrid for daily and occasional wear.
Crafted to deliver maximum foot coverage, these sandals pair effortlessly with both ethnic wear like kurtas and smart casuals including trousers and chinos. Whether you''re heading out for a casual outing, attending a traditional function, or simply relaxing on a weekend, the WF6255 keeps your style on point and your feet comfortable.
Key Features:


Classic closed-toe Roman sandal design for enhanced coverage


Breathable & supportive structure-ideal for long wear


Versatile brown color suitable for ethnic and smart casual outfits


Combines the feel of shoes with the openness of sandals


