INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-classic-boots-wgp26708-brown', 'Men''s Classic Boots - WGP26708 Brown', 'WALKAROO PLUS', 'Shoes', 'Bring timeless style to your everyday wardrobe with the Walkaroo Men''s WGP26708 Brown Chelsea Boots. Featuring a classic ankle-length silhouette, smooth-finish upper, elasticated side panels, and convenient pull tabs, these boots offer a refined look with easy slip-on functionality.
