INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('kids-slip-on-shoes-wk478-royal-blue', 'Kid''s Slip-on Shoes - WK478 Royal Blue', 'WALKAROO', 'Sneakers', 'The upper material of these Walkaroo sock shoes is stretchable hence it takes the shape of your feet. With the elastic shoe mouth design, this pair of sneakers will better fit your ankle. Due to its breathability its a perfect choice for sweaty feet. You can pair them with any of your casual wear. And these Walkaroo shoes are great to be worn at the gym, workout or dance studio. Care instructions: Allow the footwear to de-odorize regularly. Dust the surface using a clean cloth to remove the dirt.', 280.0, 299.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/WK478-ROYALBLUE-KIDS_c43fb0a2-958c-49e3-8114-139c74c8ccb9.jpg?v=1786512671&width=1920', '["https://www.walkaroo.in/cdn/shop/files/WK478-ROYALBLUE-KIDS_c43fb0a2-958c-49e3-8114-139c74c8ccb9.jpg?v=1786512671&width=1920"]'::jsonb, 6) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-leather-men-formals-shoes-wf6052-black', 'Men''s Leather formals Shoes - WF6052 Black', 'WALKAROO', 'SHOES', 'Meet our new lineup of men''s formal shoes, crafted for comfort. The new lineup of leather shoes crafted from high-quality leather offers both comfort and style. perfected for the professionals in you.Care instructions:To remove dirt or surface residue, use a soft damp cloth. Gently rub for removal. For a deeper clean, use a leather cleaner to help preserve the natural smooth oils instead of stripping them.To prevent the leather from losing suppleness over time use a wax-free leather conditioner that will nourish and restore the flexibility and suppleness of your leather goodiesLeather is a natural material, please, store your leather Shoes in a breathable, non-plastic container to prevent the growth of bacteria and mildew.', 1030.0, 1030.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/3_d738b21a-90e7-4e51-81ee-313238b5a5c5.jpg?v=1786513745&width=1920', '["https://www.walkaroo.in/cdn/shop/files/3_d738b21a-90e7-4e51-81ee-313238b5a5c5.jpg?v=1786513745&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
