INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-wedge-heel-sandals-wlr72032-teal-blue', 'Women''s Wedge Heel Sandals  - WLR72032 Turquoise Blue', 'WALKAROO', 'Sandals', 'Step into elegant comfort with the Walkaroo Ladies'' WLR72032 Teal Blue Wedge Heel Sandal . Perfectly designed as a daily wear wedge heel sandal , this footwear combines effortless style with practical comfort, making it an ideal choice for your everyday needs.
This sandal features a convenient slip-on closure  with a cross strap with toe loop design, all in a rich teal blue color . The chic wedge heel design  offers a subtle elevation while ensuring stability and ease of movement,
