INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-sandals-we8821-black', 'Men''s Daily Wear Sandals - WE8821 Black', 'FLIP-FLOPZ+', 'Sandals', 'Step into the perfect blend of comfort, style, and adjustability with the Walkaroo Men''s WE8821 Black Sandal. Designed for casual daily wear, this contemporary sandal promises "All Day Comfort" and an exceptionally "SOFT" feel . It''s your ideal companion for relaxed outings, offering both "Street Fun" and an "On Trend" look .
The upper is crafted from durable Rexin , featuring a sleek Black color scheme that offers versatile styling for various casual outfits. The slip-on design is enhanced by two broad straps across the midfoot, each equipped with convenient Velcro strap adjustments  to ensure a secure, customized, and comfortable fit for almost any foot shape.
