INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandals-wlr74030-turquoise-blue', 'Women''s Daily Wear Sandals - WLR74030 Turquoise Blue', 'WALKAROO', 'Sandals', 'Step into effortless comfort and stylish everyday wear with the Walkaroo Ladies Daily Wear Sandal WLR74030 in Turquoise Blue. Designed for women who want easy slip-on comfort, a fashionable floral look, and dependable daily support, this sandal is a practical choice for regular wear, casual outings, shopping, and relaxed day-to-day use.

