INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandals-wl7645-mauve', 'Women''s Daily Wear Sandals  - WL7645 Mauve', 'WALKAROO', 'Sandals', 'WALKAROO Women’s Daily Wear Sandals (WL7645) in Mauve are made for all-day comfort with a stylish everyday look. Featuring an easy slip-on design, a soft cushioned footbed, and a durable PU sole, these sandals are ideal for daily wear—whether you’re running errands, heading to work, or stepping out casually.

