INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-sandals-wgr53211-olive', 'Men''s Daily Wear Sandals - WGR53211 Olive', 'WALKAROO', 'Sandals', 'Experience everyday comfort and style with the Walkaroo men''s WGR53211 Olive Daily Wear Sandals. As part of India''s No. 1 PU footwear collection, these sandals are designed for lasting comfort and durability.
