INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-sports-shoes-ws9548-navy-blue', 'Walkaroo Men Walking Shoes - WS9548 Navy Blue', 'WALKAROO', 'Athletic Shoes', 'These lace up shoes from Walkaroo are sturdier & light in weight. They are comfortable & provide support to your feet. Pick different prints & pattern to get a fun & cool look. You can pair it up with your jeans, tracks, sweatpants, shorts or chinos for a casual & sporty look. You can use it for activities such as gym, tennis, running, athletic, workout, walking etc. or also as a fashion statement. Care instructions: Allow the footwear to de-odorize regularly. Dust the surface using a clean cloth to remove the dirt.', 749.0, 799.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/3_65aeea73-cd5a-404e-a6e7-4bf919726620.jpg?v=1786513742&width=1920', '["https://www.walkaroo.in/cdn/shop/files/3_65aeea73-cd5a-404e-a6e7-4bf919726620.jpg?v=1786513742&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
