INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('kids-clogs-wc4843-black-black', 'Kid''s Clogs - WC4843 Black Black', 'WALKAROO', 'Slippers', 'Walkaroo Kids Clogs are designed to provide your child with both comfort and style. Made with EVA (Ethylene Vinyl Acetate) material, these clogs are lightweight, durable, and water-resistant, making them perfect for indoor and outdoor activities.', 199.0, 229.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/WC4843-Black-KIDS_9e0a4671-8637-4035-9a6b-ae3bfa7ece31.jpg?v=1786513005&width=1920', '["https://www.walkaroo.in/cdn/shop/files/WC4843-Black-KIDS_9e0a4671-8637-4035-9a6b-ae3bfa7ece31.jpg?v=1786513005&width=1920"]'::jsonb, 7) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-slide-sandals-wlr73014-mauve', 'Women''s Slide Sandals - WLR73014 Mauve', 'WALKAROO', 'Sandals', 'Step into unparalleled comfort and style with the Walkaroo Women''s Mauve Slip-On Slide Sandals (Article: WLR73014). Designed for the modern woman, these sandals effortlessly combine affordability with superior quality, making them an essential addition to your everyday footwear collection. These sandals are also known as chappals, flats, or casual sliders.
Crafted with a durable Rexine upper, these sandals offer a sleek, smooth, and slightly textured finish in a delightful Mauve color. Featuring a convenient slip-on closure and a unique multi-strap design with a toe-loop, these slides are incredibly easy to wear and remove, perfect for those on-the-go moments.
Experience exceptional cushioning with the lightweight yet durable PU (Polyurethane) sole, engineered with a textured footbed for superior comfort and support. This innovative design ensures that every step is supported, making them ideal for casual all-day wear. The thick sole also provides good elevation and features a ridged o', 249.0, 249.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/1_be75ac04-8828-4120-907c-6dfa0aa748bf.jpg?v=1786511482&width=1920', '["https://www.walkaroo.in/cdn/shop/files/1_be75ac04-8828-4120-907c-6dfa0aa748bf.jpg?v=1786511482&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
