INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('womens-daily-wear-sandals-wlr74030-maroon', 'Women''s Daily Wear Sandals - WLR74030 Maroon', 'WALKAROO', 'Sandals', 'Step into effortless comfort and stylish everyday wear with the Walkaroo Ladies Daily Wear Sandal WLR74030 in Maroon. Designed for women who want easy slip-on comfort, a fashionable floral look, and dependable daily support, this sandal is a practical choice for regular wear, casual outings, shopping, and relaxed day-to-day use.
This ladies sandal features a slip-on design with three buckle-adjustable straps, giving it a trendy multi-strap look along with a more secure and customizable fit. The Maroon color adds a fresh and vibrant touch, while the floral printed upper creates a stylish appearance that pairs well with casual outfits, summer wear, and everyday looks.
Made with a synthetic upper with a printed finish, the sandal is designed for easy maintenance and regular use. Underfoot, the cushion sole helps provide soft comfort, while the lightweight PU sole offers support, durability, and a stable platform-style base for comfortable daily walking.
Whether you are heading out for err', 419.0, 419.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/WLR74030-MAROON-LADIES_a9e5fd91-dcfa-4e29-901b-1026be2c323e.jpg?v=1786511200&width=1920', '["https://www.walkaroo.in/cdn/shop/files/WLR74030-MAROON-LADIES_a9e5fd91-dcfa-4e29-901b-1026be2c323e.jpg?v=1786511200&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
