INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('boys-school-shoes-wv522-black', 'Boys School Shoes - WV522 Black', 'WALKAROO', 'Shoes', 'The Walkaroo WV522 Boys’ School Shoes in Black is a versatile and comfortable footwear option designed for active young boys. These shoes are crafted with a focus on both style and functionality, making them ideal for everyday wear. The lightweight design ensures comfort and ease of movement throughout the day, whether your child is running around the playground or sitting in the classroom. Made from lightweight synthetic leather and PVC, these shoes are designed for all-day wear—no polish required! Perfect for active school days, with a slip-resistant sole and snug fit. Care Instruction: No polish or shiner is needed just use a clean cloth to remove the dust.', 355.0, 355.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/01_41c29e71-3f98-4ce3-bd77-b1d5a72c1f1d.jpg?v=1786512171&width=1920', '["https://www.walkaroo.in/cdn/shop/files/01_41c29e71-3f98-4ce3-bd77-b1d5a72c1f1d.jpg?v=1786512171&width=1920"]'::jsonb, 4) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
