INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-daily-wear-comfort-sandals-wgp53205-olive', 'Men''s Daily Wear Comfort Sandals - WGP53205 Olive', 'BOUNCEEZ', 'Sandals', 'Step out in relaxed style and all-day comfort with the Walkaroo Men''s Olive Daily Wear Comfort Sandals. Featuring a stylish two-strap design crafted from durable synthetic leather, these sandals combine fashion with functionality. The slip-on structure allows easy wear, while the cushioned footbed ensures comfort with every step. The layered sole, supported by a high-quality PU outsole, provides superior grip and long-lasting durability — perfect for everyday use.
The adjustable buckle strap offers a secure and customizable fit, making these sandals an ideal choice for warm weather and casual outings. Whether you’re running errands, attending a casual gathering, or relaxing at home, these Walkaroo sandals deliver effortless comfort and contemporary style.
Key Features:


Style: Comfort Sandal

Material: Durable synthetic straps with layered sole construction

Closure: Slip-on with adjustable buckle for customized fit

Outsole: High-grip PU outsole for excellent traction and durability
', 619.0, 659.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/WGP53205-OLIVE-GENTS_9cffdf4d-872d-4547-9183-3b68e9714164.jpg?v=1786511544&width=1920', '["https://www.walkaroo.in/cdn/shop/files/WGP53205-OLIVE-GENTS_9cffdf4d-872d-4547-9183-3b68e9714164.jpg?v=1786511544&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-kids-clogs-wk423-pink', 'Walkaroo Kids Clogs  - WK423 Pink', 'WALKAROO', 'Slippers', 'These comfy clogs from Walkaroo are perfect for your kid''s active lifestyle. Made from lightweight EVA material, they''re super easy to slip on and off and won''t weigh your little one down. The soft and squishy insoles provide all-day comfort, while the sturdy soles offer great grip on any surface. With their fun and colorful designs, these clogs are sure to become your child''s go-to shoes for playtime, school, or any adventure', 284.0, 300.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/WK423-PINK_53214f16-3be6-430d-8149-f3c69bcf83a1.jpg?v=1786513017&width=1920', '["https://www.walkaroo.in/cdn/shop/files/WK423-PINK_53214f16-3be6-430d-8149-f3c69bcf83a1.jpg?v=1786513017&width=1920"]'::jsonb, 8) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
