INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-clogs-wc8814-light-grey', 'Men''s Clogs - WC8814 Light Grey', 'WALKAROO', 'Slippers', 'Step into unparalleled comfort and standout style with the Walkaroo Men''s WC8814 Light Grey Clogs. This pair distinguishes itself significantly from competitors through its unique colours and innovative **design**, in addition to its superior comfort and exceptional value.
