INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-flip-flop-sliders-wc8828-light-grey', 'Men''s Flip Flop Sliders  - WC8828 Light Grey', 'WALKAROO', 'Slippers', 'Step into effortless style and ultimate comfort with the Walkaroo Men''s WC8803 Light Grey Slider . Designed as a perfect slider for men  for everyday wear, this lightweight and stylish slipper offers "All Day Comfort" with its incredibly "SOFT" construction . It''s your ideal companion for relaxed moments, post-workout ease, or casual outings.
