INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('walkaroo-men-casuals-sandals-bt1008-blue', 'Blue Tyga Sandals For Men  - BT1008 Blue', 'BLUE TYGA', 'Sandals', 'The sole is held on your foot by a toe Thong which gives you good grip. The PU sole from Walkaroo makes it light weight, durable & gives a firm grip. You can wear these Walkaroo pair on your ethnic occasion. Pair it with your Dhoti or any other traditional wear. Care instruction: Minimal care, no maintenance needed.', 339.0, 339.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/01_8476037d-d855-45c1-bcb0-1f145d33e856.jpg?v=1786513308&width=1920', '["https://www.walkaroo.in/cdn/shop/files/01_8476037d-d855-45c1-bcb0-1f145d33e856.jpg?v=1786513308&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
INSERT INTO public.products (slug, title, brand, category, description, min_price, max_price, currency, in_stock, image_url, images, variant_count) VALUES ('mens-comfort-sandals-wgp53442-black', 'Men''s Comfort Sandals - WGP53442 Black', 'BOUNCEEZ', 'Sandals', 'Experience everyday comfort with the Walkaroo Bounceez WGP53442 in Black. Designed for men who prefer soft cushioning, supportive construction, and a secure adjustable fit, this comfort sandal combines a premium-finish upper, soft lining, arch support, and a durable cushioned insole for regular daily wear.
The sandal features a stylish Black upper with a modern dual-strap design. The broad straps provide comfortable foot coverage, while the upper strap includes an adjustable hook-and-loop closure for quick fit adjustment. The open construction keeps the sandal easy to wear for daily routines, casual outings, travel, and relaxed walking.
Underfoot, the Durable Soft Cushion Insole helps provide a comfortable feel during everyday movement. The Soft Lining is designed for added comfort against the foot, while the Arch Support Sole helps provide improved underfoot support and a more stable walking feel.
The Premium Finish of the upper gives WGP53442 a refined and versatile appearance that p', 639.0, 639.0, 'INR', True, 'https://www.walkaroo.in/cdn/shop/files/1_b93dd032-80aa-4153-952b-9d47f1c52226.jpg?v=1786540963&width=1920', '["https://www.walkaroo.in/cdn/shop/files/1_b93dd032-80aa-4153-952b-9d47f1c52226.jpg?v=1786540963&width=1920"]'::jsonb, 5) ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, min_price = EXCLUDED.min_price, max_price = EXCLUDED.max_price, in_stock = EXCLUDED.in_stock, image_url = EXCLUDED.image_url, images = EXCLUDED.images;
